/* ============================================
   NGƯU CÁT - Orange & White Theme
   ============================================ */

@layer base {
  :root {
    /* Backgrounds */
    --background: 240 10% 5%;           /* #0d0d0f */
    --foreground: 0 0% 98%;             /* White text */

    /* Cards */
    --card: 240 10% 9%;                 /* #141417 */
    --card-foreground: 0 0% 98%;

    /* Popovers */
    --popover: 240 10% 9%;
    --popover-foreground: 0 0% 98%;

    /* Primary - Vibrant Orange/Amber */
    --primary: 38 92% 50%;             /* Amber-500 */
    --primary-foreground: 0 0% 0%;

    /* Secondary - Soft Dark */
    --secondary: 240 10% 14%;
    --secondary-foreground: 0 0% 98%;

    /* Muted - Soft Dark */
    --muted: 240 10% 14%;
    --muted-foreground: 240 5% 65%;

    /* Accent - Dark Accent */
    --accent: 240 10% 14%;
    --accent-foreground: 0 0% 98%;

    /* Destructive */
    --destructive: 0 84% 60%;
    --destructive-foreground: 0 0% 100%;

    /* Borders & inputs */
    --border: 240 10% 18%;             /* #27272a dark border */
    --input: 240 10% 18%;
    --ring: 38 92% 50%;

    --radius: 0.75rem;                 /* 12px for modern sleekness */
  }

  .dark {
    --background: 240 10% 5%;
    --foreground: 0 0% 98%;
    --card: 240 10% 9%;
    --card-foreground: 0 0% 98%;
    --popover: 240 10% 9%;
    --popover-foreground: 0 0% 98%;
    --primary: 38 92% 50%;
    --primary-foreground: 0 0% 0%;
    --secondary: 240 10% 14%;
    --secondary-foreground: 0 0% 98%;
    --muted: 240 10% 14%;
    --muted-foreground: 240 5% 65%;
    --accent: 240 10% 14%;
    --accent-foreground: 0 0% 98%;
    --destructive: 0 84% 60%;
    --destructive-foreground: 0 0% 100%;
    --border: 240 10% 18%;
    --input: 240 10% 18%;
    --ring: 38 92% 50%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  html, body {
    height: 100%;
  }
  body {
    @apply bg-background text-foreground;
    font-family: 'Nunito', -apple-system, BlinkMacSystemFont, 'Hiragino Sans', 'Yu Gothic', sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
  #app {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
  }
}

/* ============================================
   Custom utilities
   ============================================ */
@layer components {
  .kawaii-shadow {
    box-shadow: 0 4px 14px rgba(255, 103, 46, 0.15);
  }
  .kawaii-shadow-lg {
    box-shadow: 0 10px 28px rgba(255, 103, 46, 0.2);
  }
  .kawaii-gradient {
    background: linear-gradient(135deg, #FF8E61 0%, #FF672E 100%);
  }
  .kawaii-card {
    @apply bg-white rounded-xl border border-[hsl(var(--border))] shadow-sm transition-all;
  }
  .kawaii-card-header {
    @apply px-5 py-3 border-b border-[hsl(var(--border))] flex items-center justify-between bg-[hsl(var(--muted))]/50 rounded-t-xl;
  }
  .kawaii-btn-primary {
    @apply kawaii-gradient text-white font-bold tracking-wide border-0 rounded-xl transition-all shadow-md hover:shadow-lg;
  }
  .kawaii-btn-primary:hover {
    filter: brightness(1.05);
  }
  .kawaii-btn-primary:active {
    transform: translateY(1px);
    box-shadow: 0 2px 5px rgba(255, 103, 46, 0.3);
  }
  .kawaii-btn-ghost {
    @apply bg-white border border-border rounded-xl text-foreground font-bold hover:bg-muted transition-colors;
  }
  .kawaii-pill {
    @apply inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold;
  }
  .kawaii-input {
    @apply w-full bg-white border border-border rounded-xl text-foreground px-4 outline-none transition-all focus:border-primary focus:ring-1 focus:ring-primary;
  }
  .kawaii-tab-active {
    @apply border-primary text-primary bg-primary/10;
  }
}

