  padding: 0 var(--spacing-xl) var(--spacing-sm);
}
.sidebar-pos__nav-item {
  display: flex;
  align-items: center;
  padding: var(--spacing-md) var(--spacing-xl);
  font-size: var(--font-size-md);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
  border-left: 3px solid transparent;
  text-decoration: none;
}
.sidebar-pos__nav-item:hover {
  background: var(--bg-gray-light);
  color: var(--text-primary);
}
.sidebar-pos__nav-item--active {
  background: var(--primary-red-light);
  color: var(--primary-red);
  border-left-color: var(--primary-red);
  font-weight: 600;
}
.sidebar-pos__nav-item-icon {
  width: 20px;
  height: 20px;
  margin-right: var(--spacing-md);
  display: flex;
  align-items: center;
  justify-content: center;
}
.sidebar-pos__footer {
  padding: var(--spacing-lg) var(--spacing-xl);
  border-top: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  background: var(--bg-white);
}
.sidebar-pos__footer-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--bg-gray-medium);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--text-secondary);
}
.sidebar-pos__footer-name {
  font-size: var(--font-size-sm);
  color: var(--text-primary);
}

/* Header Styles */
.header-pos {
  position: fixed;
  top: 0;
  left: 240px;
  right: 0;
  height: 60px;
  background: var(--bg-white);
  border-bottom: 1px solid var(--border-light);
  padding: 0 var(--spacing-xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  z-index: 99;
}
.header-pos__title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--text-primary);
}
.header-pos__branch {
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
  background: var(--bg-gray-light);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-pill);
}

/* Main Content Area */
.main-content-pos {
  margin-left: 240px;
  margin-top: 60px;
  padding: var(--spacing-xl);
  background: var(--bg-main);
  min-height: calc(100vh - 60px);
}
.main-content-pos__grid {
  display: grid;
  grid-template-columns: 45% 55%;
  gap: var(--spacing-xl);
  max-width: 1600px;
  margin: 0 auto;
}

/* Card POS Component Styles */
.card-pos {
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
  display: flex;
  flex-direction: column;
}
.card-pos__header {
  padding: var(--spacing-xl);
  border-bottom: 1px solid var(--border-light);
}
.card-pos__body {
  padding: var(--spacing-xl);
  flex: 1;
}
.card-pos__footer {
  padding: var(--spacing-xl);
  border-top: 1px solid var(--border-light);
  background: var(--bg-gray-light);
}

/* Button Styles */
.btn-pos {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-md) var(--spacing-lg);
  border: none;
  border-radius: var(--radius-md);
  font-size: var(--font-size-md);
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  text-decoration: none;
  outline: none;
}
.btn-pos:hover {
  opacity: 0.9;
  transform: scale(1.02);
}
.btn-pos:active {
  transform: scale(0.98);
}
.btn-pos--default {
  background: var(--bg-white);
  border: 1px solid var(--border-medium);
  color: var(--text-primary);
}
.btn-pos--primary {
  background: var(--primary-red);
  color: white;
}
.btn-pos--secondary {
  background: var(--primary-blue);
  color: white;
}
.btn-pos--warning {
  background: var(--primary-yellow-light);
  color: var(--primary-yellow);
}
.btn-pos--danger {
  background: var(--error-red-light);
  color: var(--error-red);
}
.btn-pos--sm {
  padding: var(--spacing-sm) var(--spacing-md);
  font-size: var(--font-size-sm);
}
.btn-pos--lg {
  padding: var(--spacing-md) var(--spacing-xl);
  font-size: var(--font-size-lg);
}

/* Badge Styles */
.badge-pos {
  display: inline-flex;
  align-items: center;
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: var(--radius-pill);
  font-size: var(--font-size-sm);
  font-weight: 600;
}
.badge-pos--primary {
  background: var(--primary-red-light);
  color: var(--primary-red);
}
.badge-pos--secondary {
  background: var(--bg-gray-light);
  color: var(--text-secondary);
}
.badge-pos--success {
  background: var(--success-green-light);
  color: var(--success-green);
}

/* Chip/Filter Styles */
.chip-pos {
  display: inline-flex;
  align-items: center;
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-pill);
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  border: 1px solid var(--border-medium);
  background: var(--bg-white);
  color: var(--text-secondary);
}
.chip-pos:hover {
  border-color: var(--primary-red);
  color: var(--primary-red);
}
.chip-pos--active {
  background: var(--primary-red);
  color: white;
  border-color: var(--primary-red);
}

/* Input Styles */
.input-pos {
  width: 100%;
  padding: var(--spacing-md);
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-md);
  font-size: var(--font-size-md);
  transition: all var(--transition-fast);
}
.input-pos:focus {
  outline: none;
  border-color: var(--primary-blue);
  box-shadow: 0 0 0 3px rgba(25, 118, 210, 0.1);
}

/* Menu Card Styles - Prompt 3 specifies 140px fixed height */
.menu-card-pos {
  background: var(--bg-white);
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  height: 140px;
  display: flex;
  flex-direction: column;
  transition: all var(--transition-normal);
  cursor: pointer;
  position: relative;
}
.menu-card-pos:hover {
  border-color: var(--primary-red);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

/* Responsive Media Queries */
@media (max-width: 1400px) {
  .main-content-pos__grid {
    grid-template-columns: 40% 60%;
  }
}
@media (max-width: 1024px) {
  .sidebar-pos {
    width: 200px;
  }
  .header-pos {
    left: 200px;
  }
  .main-content-pos {
    margin-left: 200px;
  }
  .main-content-pos__grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 768px) {
  .sidebar-pos {
    transform: translateX(-100%);
    transition: transform var(--transition-slow);
  }
  .sidebar-pos--open {
    transform: translateX(0);
  }
  .header-pos {
    left: 0;
  }
  .main-content-pos {
    margin-left: 0;
    padding: var(--spacing-md);
  }
}

